<script setup>
import { useRouter } from 'vue-router'
import { state,money } from '../lib/store'
import StatusBadge from './StatusBadge.vue'
const props=defineProps({rows:Array,compact:Boolean})
const emit=defineEmits(['copy','audit','dispute','pay'])
const router=useRouter()
function review(row){const order=state.orders.find(o=>o.taskId===row.id&&o.status==='待验收');router.push(order?`/merchant/review/${order.id}`:`/tasks/${row.id}`)}
</script>
<template><el-table :data="rows" row-key="id" style="width:100%"><el-table-column label="任务" :min-width="compact?240:270"><template #default="{row}"><div class="table-task"><img v-if="!compact" :src="row.image" alt=""/><div><strong>{{row.title}}</strong><div class="tag-row"><span class="plain-tag">{{row.category}}</span></div></div></div></template></el-table-column><el-table-column v-if="!compact" prop="mode" label="接单模式" width="90"/><el-table-column label="赏金" width="105"><template #default="{row}"><strong class="price-text">¥{{money(row.cents)}}</strong></template></el-table-column><el-table-column label="状态" width="108"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column><el-table-column label="更新时间" prop="updated" width="145"/><el-table-column label="操作" :min-width="compact?150:215"><template #default="{row}"><div class="table-actions"><el-button link type="primary" @click="router.push(`/tasks/${row.id}`)">查看</el-button><el-button v-if="row.status==='待验收'" link type="primary" @click="review(row)">去验收</el-button><el-button v-else-if="row.mode==='比稿'&&row.status==='招募中'" link type="primary" @click="router.push(`/merchant/bids?task=${row.id}`)">选人中标</el-button><el-button v-else-if="row.status==='审核中'" link type="primary" @click="emit('audit',row)">模拟审核通过</el-button><el-button v-else-if="row.status==='待支付'" link type="primary" @click="emit('pay',row)">模拟支付</el-button><el-button v-else-if="row.status==='纠纷中'" link type="primary" @click="emit('dispute',row)">仲裁进度</el-button><el-button v-else-if="row.status==='进行中'" link type="primary" @click="router.push('/messages?role=merchant&chat=creator')">联系创作者</el-button><el-button v-if="!compact" link type="primary" @click="emit('copy',row)">{{row.status==='草稿'?'继续编辑':'复制再发'}}</el-button></div></template></el-table-column><template #empty><el-empty description="没有符合条件的任务" :image-size="65"/></template></el-table></template>
